    print(f'gateway: {list(c[\"gateway\"].keys()) if isinstance(c[\"gateway\"], dict) else c[\"gateway\"]}')
"

cat ~/.nanobot/config.json | python3 -c "
import json,sys
c=json.load(sys.stdin)
for k,v in c.items():
    if isinstance(v,str) and len(v)>5:
        print(f'{k}: {v[:20]}...')
    elif isinstance(v,dict):
        print(f'{k}: dict keys={list(v.keys())}')
    else:
        print(f'{k}: {v}')
